  (
    'mongolian-huushuur',
    'Шүүслэг Мөнгөн Хуушуур',
    'Juicy Silver Mongolian Huushuur',
    'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?auto=format&fit=crop&w=800&q=80',
    ARRAY['Монгол хоол', 'Хуушуур', 'Үндсэн хоол'],
    '35 мин',
