    ARRAY['Үхрийн мах', 'Гурил', 'Сүү', 'Бяслаг', 'Томат соус', 'Сонгино'],
    '[{"stepNumber":1,"title":"Сонгино & Сармис хуурч бэлтгэх","titleEn":"Sauté Onions & Garlic","description":"Гүн хайруулын тавгаа дунд гал дээр халааж, 2 хоолны халбага оливын тосонд нарийн жижиглэсэн сонгино, сармисаа алтан шар өнгөтэй, анхилуун үнэртэй болтол 4-5 минут хуурна.","descriptionEn":"Heat olive oil in a deep pan, sauté finely chopped onions and garlic until translucent and fragrant.","image":"https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=800&q=80","sisterTip":"Сонгиноо зөөлөн гал дээр карамельжуулбал соусны амт байгалийн чихэрлэг бөгөөд тансаг болдог.","sisterTipEn":"Slowly caramelizing onions creates a naturally sweet flavor base.","timerMinutes":5,"heatLevel":"Medium","stepIngredients":["Сонгино (1 ш жижиглэсэн)","Сармис (3 хумс)","Оливын тос (2 хоолны халбага)"],"toolsNeeded":["Гүн хайруулын таваг","Модон хутгуур"]},{"stepNumber":2,"title":"Үхрийн мах & Болоньез соус бэлтгэх","titleEn":"Bolognese Meat Sauce","description":"Хуурсан сонгино дээрээ үхрийн татсан махаа нэмж, бөөгнөрөхгүйгээр задартал хуурна. Дараа нь томат паста, орегано, давс, хар перец нэмж 12 минут зөөлөн гал дээр самран буцалгана.","descriptionEn":"Add minced beef, cook until browned. Stir in tomato sauce, oregano, salt, and pepper. Simmer for 12 mins.","image":"https://images.unsplash.com/photo-1546549032-9571cd6b27df?auto=format&fit=crop&w=800&q=80","sisterTip":"Соус буцалж байхад 1 чимх саахар нэмбэл томатын хүчиллэг чанарыг зөөллөж амтыг нь тэнцвэржүүлнэ.","sisterTipEn":"Adding a pinch of sugar balances the acidity of the tomatoes.","timerMinutes":12,"heatLevel":"Low","stepIngredients":["Үхрийн татсан мах (500 гр)","Томат паста (300 мл)","Орегано амтлагч (1 цайны халбага)","Давс & Хар перец"],"toolsNeeded":["Модон хутгуур","Таглаа"]},{"stepNumber":3,"title":"Бешамель (Цагаан соус) чанах","titleEn":"Prepare Béchamel Sauce","description":"Жижиг саванд шар тосоо хайлуулж гурилаа нэмэн 1 минут хуурна. Бүлээн сүүгээ бага багаар гоожуулан хутгууртаар тасралтгүй хутгаж, өтгөртөл 6-8 минут зөөлөн гал дээр чанана.","descriptionEn":"Melt butter, add flour, cook 1 min. Gradually whisk in warm milk and cook until thick and creamy.","image":"https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=800&q=80","sisterTip":"Сүүгээ бүлээнээр нь бага багаар нэмж хутгуурыг зогсолтгүй хөдөлгөвөл соус бөөгнөрөхгүй торгомсог болно.","sisterTipEn":"Whisk continuously while pouring warm milk to achieve a silky smooth texture.","timerMinutes":8,"heatLevel":"Low","stepIngredients":["Шар тос / Маргарин (50 гр)","Гурил (2 хоолны халбага)","Бүлээн сүү (500 мл)","Мускат самар (1 чимх)"],"toolsNeeded":["Шөлний жижиг сав","Гар хутгуур (Whisk)"]},{"stepNumber":4,"title":"Лазанья гоймон чанах ба зөөлрүүлэх","titleEn":"Boil Lasagna Sheets","description":"Том тогоонд усаа сайн буцалгаж 1 чимх давс нэмнэ. Гоймоны хуудсуудыг 5-6 минут чанаж зөөлрүүлээд шүүж, наалдуулахгүйн тулд цэвэр алчуур дээр дэлгэн тавина.","descriptionEn":"Boil lasagna sheets in salted water for 5-6 mins. Drain and lay flat on a clean cloth to prevent sticking.","image":"https://images.unsplash.com/photo-1621996346565-e3d5d6281318?auto=format&fit=crop&w=800&q=80","sisterTip":"Чанах усандаа хэдэн дусал оливын тос дусгавал гоймон чанах үед бие биедээ наалдахгүй.","sisterTipEn":"A drop of olive oil in boiling water keeps sheets from sticking together.","timerMinutes":6,"heatLevel":"High","stepIngredients":["Лазанья гоймон (12 хуудас)","Давстай буцалсан ус"],"toolsNeeded":["Том тогоо","Шүүгч сэрээ"]},{"stepNumber":5,"title":"Хэвэнд давхарлан угсрах (Layering)","titleEn":"Assemble Lasagna Layers","description":"Дөрвөлжин шилэн хэвний ёроолд бешамель соусыг нимгэн түрхэнэ. Гоймон -> Болоньез махны соус -> Бешамель цагаан соус -> Моцарелла бяслаг гэх дарааллаар 3-4 үе давхарлана.","descriptionEn":"Spread béchamel on baking dish bottom. Layer sheets, meat sauce, béchamel, and mozzarella cheese.","image":"https://images.unsplash.com/photo-1574894709920-11b28e7367e3?auto=format&fit=crop&w=800&q=80","sisterTip":"Хамгийн дээд үе дээр бешамель соус болон Моцарелла бяслагаа зузаан бүрж цацаарай.","sisterTipEn":"Top with a rich layer of béchamel and shredded mozzarella for maximum cheesiness.","timerMinutes":5,"heatLevel":null,"stepIngredients":["Моцарелла бяслаг (250 гр хэрчсэн)","Үрсэн Пармезан бяслаг (50 гр)"],"toolsNeeded":["Шарах шүүгээний дөрвөлжин шилэн хэв"]},{"stepNumber":6,"title":"Шарах шүүгээнд жигнэж шаргалдуулах","titleEn":"Bake to Golden Perfection","description":"190°C хүртэл халаасан шарах шүүгээнд фольга цаасаар таглаж 20 минут, дараа нь цаасыг авч бяслагийг алтан бор шаржигнасан болтол 8 минут шарна. Гаргаад 10 минут амраасны дараа зүснэ.","descriptionEn":"Cover with foil and bake at 190°C for 20 mins. Uncover and bake 8 mins until cheese is golden brown. Rest 10 mins.","image":"https://images.unsplash.com/photo-1546549032-9571cd6b27df?auto=format&fit=crop&w=800&q=80","sisterTip":"Шарах шүүгээнээс гарсан дор нь шууд зүсэлгүй 10 минут амраавал давхаргууд нь нурахгүй, тэгш сайхан зүсэгдэнэ.","sisterTipEn":"Letting the lasagna rest for 10 mins sets the layers perfectly for neat slicing.","timerMinutes":28,"heatLevel":"Medium","stepIngredients":["Амраасан Лазанья"],"toolsNeeded":["Шарах шүүгээ (190°C)","Фольга цаас","Тогоочийн хутга"]}]'::jsonb
  ),
