    '{"calories":520,"protein":24,"carbs":62,"fat":20}'::jsonb,
    ARRAY['Гурил', 'Өндөг', 'Бяслаг', 'Сармис'],
    '[{"stepNumber":1,"title":"Спагетти гоймон чанах","titleEn":"Boil Spaghetti Al Dente","description":"Том тогоонд ус буцалгаж 1 хоолны халбага давс нэмнэ. Спагетти гоймонгоо хийж сав дахь зааврын дагуу (ихэвчлэн 9-10 мин) al dente буюу шүдэнд бага зэрэг зууртай болтол чанана. Чанасан уснаас 1 аяга нөөцлөж авна.","descriptionEn":"Boil pasta in heavily salted water for 9-10 mins until al dente. Reserve 1 cup of pasta water before draining.","image":"https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=800&q=80","sisterTip":"Гоймон чанасан давстай усыг заавал нөөцөлж аваарай — энэ бол карбонарын соусыг хамгийн торгомсог, кремлэг болгодог нууц зэвсэг!","sisterTipEn":"Pasta water is liquid gold for carbonara — its starch makes the sauce unbelievably silky and emulsified.","timerMinutes":10,"heatLevel":"High","stepIngredients":["Спагетти гоймон (400 гр)","Давстай буцалсан ус (4 л)","Нөөцлөх ус (1 аяга)"],"toolsNeeded":["Том тогоо","Гоймоны ус нөөцлөх аяга","Шүүгч сэрээ"]},{"stepNumber":2,"title":"Гуанчале / Бекон шарах","titleEn":"Render Guanciale / Bacon","description":"Хайруулын тавагт тос хийлгүй гуанчале буюу бекон мах нарийн зурааслан хэрчсэнийг тавьж зөөлөн гал дээр 4-5 минут тосыг нь гаргаж, шаржигнатал хуурна.","descriptionEn":"Without any added oil, render guanciale/bacon strips in pan on medium-low for 4-5 mins until crispy fat renders out.","image":"https://images.unsplash.com/photo-1621996346565-e3d5d6288307?auto=format&fit=crop&w=800&q=80","sisterTip":"Тос нэмэхгүйгээр өөрийн тосыг нь гаргах нь бекон/гуанчале-г маш шаржигнасан, дотор нь хайлмаг болгодог шүү.","sisterTipEn":"No added oil — render the fat from the pork itself for the most authentic, rich carbonara flavor.","timerMinutes":5,"heatLevel":"Low","stepIngredients":["Гуанчале / Бекон (150 гр нарийн зурааслан)"],"toolsNeeded":["Хайруулын таваг","Металл хутгуур"]},{"stepNumber":3,"title":"Өндөг & Бяслагны холимог бэлтгэх","titleEn":"Whisk Egg & Cheese Mixture","description":"Том аяганд өндгийн 3 шар, Пармезан (эсвэл Пекорино) бяслаг сайн үрж хийж, хар перец сайтар нэмнэ. Сайтар хутгаж жигд холино. Энэ холимог галд огт хүрэхгүй — зөвхөн гоймоны дулаанаар зуурагдана.","descriptionEn":"In a bowl, whisk 3 egg yolks with finely grated parmesan and generous black pepper. This MUST never touch direct heat.","image":"https://images.unsplash.com/photo-1612874742237-6526221588e3?auto=format&fit=crop&w=800&q=80","sisterTip":"Өндгийг шууд галд тавивал тэр дороо бүлэгнэж хатна — Scrambled Eggs болчихно! Заавал галаас нь холдуулаарай.","sisterTipEn":"NEVER put eggs near heat — they WILL scramble instantly. The only heat they need is from the warm pasta itself.","timerMinutes":null,"heatLevel":null,"stepIngredients":["Өндгийн шар (3 ширхэг)","Пармезан бяслаг (80 гр нарийн үрсэн)","Хар перец (1 цайны халбага шинэ бутарсан)"],"toolsNeeded":["Холих аяга","Хутгуур","Бяслаг үрэгч"]},{"stepNumber":4,"title":"Бүх зүйлийг нэгтгэх — Галаас гаргасны дараа!","titleEn":"Combine Off Heat — This Step is Sacred","description":"Гоймоныг шүүж беконтой хайруулын тавагт хийнэ. ГАЛААС ГАРГА. Өндгийн холимогоо хийж хурдан хутгана. Нөөцөлсөн гоймоны уснаас 2-3 хоолны халбага нэмж, торгомсог кремлэг болтол хурдан хутгана.","descriptionEn":"Drain pasta into bacon pan. REMOVE FROM HEAT. Add egg mixture immediately. Toss rapidly. Add pasta water 1 tbsp at a time until glossy and creamy.","image":"https://images.unsplash.com/photo-1612874742237-6526221588e3?auto=format&fit=crop&w=800&q=80","sisterTip":"Гоймоны ус нэмэх нь өндгийг тогтвортой эмульс болгодог — хэт их нэмэлгүй 1-2 хоолны халбагаар тохируулаарай.","sisterTipEn":"Add pasta water one spoon at a time — it emulsifies the eggs into glossy silk. This is the soul of real carbonara.","timerMinutes":3,"heatLevel":null,"stepIngredients":["Чанасан Спагетти","Шаржигнасан Бекон","Өндөг-Бяслагны Холимог","Нөөцөлсөн Гоймоны Ус (2-4 хоолны халбага)"],"toolsNeeded":["2 халбага (хурдан хутгахад)","Дулаан хоолны аяга"]}]'::jsonb
